&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes.html&quot; title=&quot;Tableau r&#233;capitulatif des armes&quot;&gt;Les armes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes.html&quot; title=&quot;Descriptions individuelles des armes&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes.html&quot; title=&quot;Caract&#233;ristiques des armes&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armes-&#192;-Feu.html&quot; title=&quot;Tableau r&#233;capitulatif des armes &#224; feu&quot;&gt;Les armes &#224; feu&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armes-&#192;-Feu.html&quot; title=&quot;Descriptions individuelles des armes &#224; feu&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes-&#192;-Feu.html&quot; title=&quot;Caract&#233;ristiques des armes &#224; feu&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures.html&quot; title=&quot;Tableau r&#233;capitulatif des armures&quot;&gt;Les armures&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Armures.html&quot; title=&quot;Descriptions individuelles des armures&quot;&gt;descriptions&lt;/a&gt;)&lt;/li&gt;
	&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armures.html&quot; title=&quot;Caract&#233;ristiques des armures&quot;&gt;caract&#233;ristiques&lt;/a&gt;&lt;/li&gt;&lt;/ul&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mat&#233;riaux-Sp&#233;ciaux.html&quot; title=&quot;Les mat&#233;riaux sp&#233;ciaux&quot;&gt;Les mat&#233;riaux sp&#233;ciaux&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Animaux,%20montures%20et%20leur%20%C3%A9quipement.ashx#&quot; title=&quot;Animaux, montures et leur &#233;quipement&quot;&gt;Animaux, montures et leur &#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chroniques-Des-&#201;claireurs.html&quot; title=&quot;Chroniques des Explorateurs&quot;&gt;Chroniques des Explorateurs&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;%C3%89quipement%20daventurier.ashx#&quot; title=&quot;&#201;quipement d&amp;#39;aventurier&quot;&gt;&#201;quipement d&#39;aventurier&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Focalisateurs%20de%20canalisation.ashx#&quot; title=&quot;Focalisateurs de canalisation&quot;&gt;Focalisateurs de canalisation&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H%C3%A9bergement%20et%20services.ashx#&quot; title=&quot;H&#233;bergement et services&quot;&gt;H&#233;bergement et services&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Jeux.ashx#&quot; title=&quot;Jeux&quot;&gt;Jeux&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March%C3%A9%20noir.ashx#&quot; title=&quot;March&#233; noir&quot;&gt;March&#233; noir&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moyens%20de%20transport.ashx#&quot; title=&quot;Moyens de transport&quot;&gt;Moyens de transport&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nourriture%20et%20Boissons.ashx#&quot; title=&quot;Nourriture et Boissons&quot;&gt;Nourriture et Boissons&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20de%20comp%C3%A9tences.ashx#&quot; title=&quot;Outils de comp&#233;tences&quot;&gt;Outils de comp&#233;tences&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Trousses%20d%C3%A9quipement.ashx#&quot; title=&quot;Trousses d&amp;#39;&#233;quipement&quot;&gt;Trousses d&#39;&#233;quipement&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;V%C3%AAtements.ashx#&quot; title=&quot;V&#234;tements&quot;&gt;V&#234;tements&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poisons.ashx#&quot; title=&quot;Les poisons  &quot;&gt;Poisons&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;td&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Armes%20alchimiques.ashx#&quot; title=&quot;Armes alchimiques&quot;&gt;Armes alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Outils%20alchimiques.ashx#&quot; title=&quot;Outils alchimiques&quot;&gt;Outils alchimiques&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rem%C3%A8des%20alchimiques.ashx#&quot; title=&quot;Rem&#232;des alchimiques&quot;&gt;Rem&#232;des alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Argent-Et-Richesse.html&quot; title=&quot;Argent et richesse&quot;&gt;L&#39;argent et la richesse&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Marchandises.html&quot; title=&quot;Marchandises&quot;&gt;Les marchandises&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poids-Transportable.html&quot; title=&quot;Poids transportable&quot;&gt;Le poids transportable&lt;/a&gt;&lt;/li&gt;
    &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;actifs-Alchimiques.html&quot; title=&quot;R&#233;actifs alchimiques&quot;&gt;Les r&#233;actifs alchimiques&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;Les r&#233;actifs suivants sont purifi&#233;s par de longs processus &#224; partir de leur &#233;tat brut pour &#234;tre utilis&#233;s dans des recettes alchimiques. Chaque r&#233;actif alchimique peut &#233;galement &#234;tre utilis&#233; comme composante de puissance alchimique, augmentant les effets de certains sorts lorsqu&#39;il est utilis&#233; comme &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;composante mat&#233;rielle&lt;/a&gt; suppl&#233;mentaire. Les composantes de puissance alchimique ont &#233;t&#233; introduites pour la premi&#232;re fois dans le Compagnon du joueur : Armurerie de l’aventurier (et sont d&#233;crites ci-dessous). L&#39;utilisation d&#39;un r&#233;actif comme composante de puissance alchimique n&#233;cessite un certain nombre de doses du r&#233;actif, n&#39;affecte que les sorts qui r&#233;pondent aux crit&#232;res sp&#233;cifi&#233;s et n&#39;augmente qu&#39;un effet que le sort produit d&#233;j&#224; (par exemple, un personnage peut utiliser de la poudre noire comme composante de puissance alchimique uniquement pour un sort qui inflige des d&#233;g&#226;ts d’&#233;nergie destructive). Les r&#233;actifs ne se cumulent ni avec eux- m&#234;mes ni entre eux et sont consomm&#233;s apr&#232;s utilisation.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;Une composante de puissance alchimique est un objet alchimique utilis&#233; comme &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;composante mat&#233;rielle&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;focalisateur&lt;/a&gt; d&#39;un sort afin de modifier ou d&#39;am&#233;liorer les effets normaux du sort. Ce qui suit est un &#233;chantillon de ces effets ; le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; peut autoriser d&#39;autres combinaisons. Les sorts suivis d&#39;un (M) d&#233;pensent l&#39;objet alchimique en tant que composante mat&#233;rielle ; ceux suivis d&#39;un (F) utilisent l&#39;objet comme focalisateur et ne le d&#233;pensent donc pas. Dans les deux cas, l&#39;objet alchimique ne produit pas son effet normal et n&#39;affecte aucun autre param&#232;tre du sort. Un personnage ne peut pas utiliser le m&#234;me objet comme focalisateur et comme composante mat&#233;rielle en m&#234;me temps.&lt;br /&gt;&lt;br /&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Acide&quot; href=&quot;#Acide&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Acide (&lt;a class=&quot;pagelink&quot; href=&quot;Acide-(Objet).html&quot; title=&quot;Acide&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Acide__lien__0&quot; href=&quot;#Acide__lien__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Une flasque d’acide classique a beaucoup d’utilisation comme composante de puissance, plus particuli&#232;rement avec les sorts offensifs.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (10 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspersion-Acide.html&quot; title=&quot;Aspersion acide&quot;&gt;aspersion acide&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brume-Acide.html&quot; title=&quot;Brume acide&quot;&gt;brume acide&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Fl&#232;che-Acide.html&quot; title=&quot;Fl&#232;che acide&quot;&gt;fl&#232;che acide&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Graisse.html&quot; title=&quot;Graisse&quot;&gt;graisse&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Glace.html&quot; title=&quot;Mur de glace&quot;&gt;mur de glace&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; L’acide peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Aspersion acide (F).&lt;/b&gt; Le sort inflige +1 point de d&#233;g&#226;ts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aspersion acide (M).&lt;/b&gt; L’acide du sort dure 1 round suppl&#233;mentaire.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Brume acide (M).&lt;/b&gt; Le rayon et la hauteur de la brume augmente de 1,5 m.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dissipation de la magie (M).&lt;/b&gt; Utiliser de l’acide comme composante mat&#233;rielle en tentant de dissiper ou de contrer un sort ou un effet du sous-type de la terre offre un bonus de +2 au test de dissipation. Ce bonus s’applique aussi bien sur &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-Supr&#234;me.html&quot; title=&quot;Dissipation supr&#234;me&quot;&gt;dissipation supr&#234;me&lt;/a&gt;&lt;/i&gt; que sur tout autre sort utilis&#233; pour effectuer un &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Contresort.html&quot; title=&quot;contresort&quot;&gt;contresort&lt;/a&gt; (par exemple, si le personnage poss&#232;de le don &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Contresort.html&quot; title=&quot;Science du contresort&quot;&gt;Science du contresort&lt;/a&gt;).&lt;/li&gt;&lt;li&gt;&lt;b&gt;Fl&#232;che acide (M).&lt;/b&gt; L’acide du sort dure 1 round suppl&#233;mentaire.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Graisse (M).&lt;/b&gt; La graisse est acide et inflige 1 point de d&#233;g&#226;ts d’acide par round &#224; toute cr&#233;ature dans la zone d’effet ou tenant l’objet graiss&#233;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Mur de glace (M).&lt;/b&gt; Pour chaque flasque d’acide utilis&#233;e comme composante de puissance, le personnage peut d&#233;signer un carr&#233; de 3 m de c&#244;t&#233; du &lt;i&gt;mur de glace&lt;/i&gt; qui, s’il est creus&#233;, inflige 1d6 points de d&#233;g&#226;ts d’acide en plus des d&#233;g&#226;ts de froid.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Anti-maladie&quot; href=&quot;#Anti-maladie&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Anti-maladie (&lt;a class=&quot;pagelink&quot; href=&quot;Anti-Maladie-(Objet).html&quot; title=&quot;Anti-maladie&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Anti-maladie__lien__1&quot; href=&quot;#Anti-maladie__lien__1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Certains sorts de gu&#233;rison ont de meilleurs effets lorsqu’ils sont utilis&#233;s avec cette substance.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (50 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Festin-Des-H&#233;ros.html&quot; title=&quot;Festin des h&#233;ros&quot;&gt;festin des h&#233;ros&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gu&#233;rison-Des-Maladies.html&quot; title=&quot;Gu&#233;rison des maladies&quot;&gt;gu&#233;rison des maladies&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; L’anti-maladie peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Festin des h&#233;ros (M).&lt;/b&gt; Pour chaque fiole d’anti-maladie utilis&#233;e comme composante de puissance, une cr&#233;ature consommant le festin gagne les avantages d’un &lt;a class=&quot;pagelink&quot; href=&quot;Anti-Maladie-(Objet).html&quot; title=&quot;Anti-maladie&quot;&gt;anti-maladie&lt;/a&gt; pendant 12 heures. Le go&#251;t habituellement infect de l’anti-maladie de modifie pas le go&#251;t du festin.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Gu&#233;rison des maladies (M).&lt;/b&gt; Ajoute un bonus de +2 au test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; du personnage pour soigner les maladies de la cible.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Antitoxine&quot; href=&quot;#Antitoxine&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Antitoxine (&lt;a class=&quot;pagelink&quot; href=&quot;Antitoxine-(Objet).html&quot; title=&quot;Antitoxine&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Antitoxine__lien__2&quot; href=&quot;#Antitoxine__lien__2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Comme l’anti-maladie, cette substance am&#233;liore certains sorts de gu&#233;rison.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (50 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Neutralisation-Du-Poison.html&quot; title=&quot;Neutralisation du poison&quot;&gt;neutralisation du poison&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; L’antitoxine peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Neutralisation du poison (M).&lt;/b&gt; Ajoute un bonus de +2 au test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; du personnage pour neutraliser les poisons qui affectent la cible. L’antitoxine n’a aucun effet si le sort est lanc&#233; sur un objet.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;B&#226;ton fumig&#232;ne&quot; href=&quot;#B&#226;ton fumig&#232;ne&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;B&#226;ton fumig&#232;ne (&lt;a class=&quot;pagelink&quot; href=&quot;B&#226;ton-Fumig&#232;ne-(Objet).html&quot; title=&quot;B&#226;ton fumig&#232;ne&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;B&#226;ton_fumig&#232;ne__lien__3&quot; href=&quot;#B&#226;ton_fumig&#232;ne__lien__3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces objets fonctionnent mieux avec des sorts qui cr&#233;ent des nuages ou de la fum&#233;e.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (20 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brume-De-Dissimulation.html&quot; title=&quot;Brume de dissimulation&quot;&gt;brume de dissimulation&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nappe-De-Brouillard.html&quot; title=&quot;Nappe de brouillard&quot;&gt;nappe de brouillard&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrotechnie.html&quot; title=&quot;Pyrotechnie&quot;&gt;pyrotechnie&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; Les b&#226;tons fumig&#232;nes peuvent &#234;tre utilis&#233;s comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Brume de dissimulation (M).&lt;/b&gt; Le sort cr&#233;e un &#233;pais brouillard plut&#244;t que de la brume. Ce brouillard ne peut pas &#234;tre dispers&#233; par des sorts de feu et se dissipe naturellement apr&#232;s 1 minute.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Nappe de brouillard (M).&lt;/b&gt; Augmente le rayon du nuage de 1,5 m.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pyrotechnie (M).&lt;/b&gt; Augmente le rayon du nuage de 1,5 m et sa dur&#233;e de 2 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Feu gr&#233;geois&quot; href=&quot;#Feu gr&#233;geois&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Feu gr&#233;geois (&lt;a class=&quot;pagelink&quot; href=&quot;Feu-Gr&#233;geois-(Objet).html&quot; title=&quot;Feu gr&#233;geois&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Feu_gr&#233;geois__lien__4&quot; href=&quot;#Feu_gr&#233;geois__lien__4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cette sp&#233;cialit&#233; naine peut prolonger la dur&#233;e des sorts de feu.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (20 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Boule-De-Feu.html&quot; title=&quot;Boule de feu&quot;&gt;boule de feu&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-&#201;nergies-Destructives.html&quot; title=&quot;Protection contre les &#233;nergies destructives&quot;&gt;protection contre les &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-Ardent.html&quot; title=&quot;Rayon ardent&quot;&gt;rayon ardent&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sph&#232;re-De-Feu.html&quot; title=&quot;Sph&#232;re de feu&quot;&gt;sph&#232;re de feu&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; Le feu gr&#233;geois peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Boule de feu (M).&lt;/b&gt; Une cible par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; qui rate son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; (au choix du personnage) prend feu comme si elle avait &#233;t&#233; touch&#233;e par un &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Gr&#233;geois-(Objet).html&quot; title=&quot;Feu gr&#233;geois&quot;&gt;feu gr&#233;geois&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Mains br&#251;lantes (M).&lt;/b&gt; Une cible par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; qui rate son jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; (au choix du personnage) prend feu comme si elle avait &#233;t&#233; touch&#233;e par un &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Gr&#233;geois-(Objet).html&quot; title=&quot;Feu gr&#233;geois&quot;&gt;feu gr&#233;geois&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Protection contre les &#233;nergies destructives (M).&lt;/b&gt; S’il est lanc&#233; pour prot&#233;ger du froid, augmente de 5 le nombre de d&#233;g&#226;ts de froid absorb&#233;s.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Rayon ardent (F).&lt;/b&gt; Ajoute un bonus de circonstances de +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdattaque.html&quot; title=&quot;jet dattaque&quot;&gt;jet d’attaque&lt;/a&gt; de tous les rayons lanc&#233;s par le sort.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Rayon ardent (M).&lt;/b&gt; Toutes les cibles bless&#233;es par un &lt;i&gt;rayon ardent&lt;/i&gt; prennent feu comme si elle avait &#233;t&#233; touch&#233;e par un &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html#Feu gr&#233;geois&quot; title=&quot;Armes alchimiques&quot;&gt;feu gr&#233;geois&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;sistance aux &#233;nergies destructives (M).&lt;/b&gt; S’il est lanc&#233; pour prot&#233;ger du froid, passe la r&#233;sistance au froid &#224; 12. &#192; partir du &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; 7, le personnage peut utiliser deux flasques de feu gr&#233;geois comme composante de puissance pour passer la r&#233;sistance au froid &#224; 24. &#192; partir du &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; 11, le personnage peut utiliser trois flasques de feu gr&#233;geois comme composante de puissance pour passer la r&#233;sistance au froid &#224; 36.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sph&#232;re de feu (M).&lt;/b&gt; Toutes les cibles bless&#233;es par la &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sph&#232;re-De-Feu.html&quot; title=&quot;Sph&#232;re de feu&quot;&gt;sph&#232;re de feu&lt;/a&gt;&lt;/i&gt; prennent feu comme si elle avait &#233;t&#233; touch&#233;e par un &lt;a class=&quot;pagelink&quot; href=&quot;Feu-Gr&#233;geois-(Objet).html&quot; title=&quot;Feu gr&#233;geois&quot;&gt;feu gr&#233;geois&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Gardelame&quot; href=&quot;#Gardelame&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Gardelame (&lt;a class=&quot;pagelink&quot; href=&quot;Gardelame-(Objet).html&quot; title=&quot;Gardelame&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Gardelame__lien__5&quot; href=&quot;#Gardelame__lien__5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les armes et les armures ne sont pas les seules choses que le gardelame prot&#232;ge.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (40 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Fer.html&quot; title=&quot;Mur de fer&quot;&gt;mur de fer&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; Le gardelame peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Mur de fer (M).&lt;/b&gt; Pour chaque pot de gardelame utilis&#233; comme composante de puissance, le personnage peut d&#233;signer un carr&#233; de 3 m du &lt;i&gt;mur de fer&lt;/i&gt; qui obtient une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; &#224; l’acide de 10 et une &lt;a class=&quot;pagelink&quot; href=&quot;Immunit&#233;-(Capacit&#233;).html&quot; title=&quot;Immunit&#233; (Ext ou Sur)&quot;&gt;immunit&#233;&lt;/a&gt; aux attaques de rouille.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Glace liquide&quot; href=&quot;#Glace liquide&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Glace liquide (&lt;a class=&quot;pagelink&quot; href=&quot;Glace-Liquide-(Objet).html&quot; title=&quot;Glace liquide&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Glace_liquide__lien__6&quot; href=&quot;#Glace_liquide__lien__6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cette substance renforce la magie du froid.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (40 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;C&#244;ne-De-Froid.html&quot; title=&quot;C&#244;ne de froid&quot;&gt;c&#244;ne de froid&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;servation-Des-Morts.html&quot; title=&quot;Pr&#233;servation des morts&quot;&gt;pr&#233;servation des morts&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Protection-Contre-Les-&#201;nergies-Destructives.html&quot; title=&quot;Protection contre les &#233;nergies destructives&quot;&gt;protection contre les &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rayon-De-Givre.html&quot; title=&quot;Rayon de givre&quot;&gt;rayon de givre&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; La glace liquide peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;C&#244;ne de froid (M).&lt;/b&gt; Le sort inflige +1 point de d&#233;g&#226;ts par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pr&#233;servation des morts (M).&lt;/b&gt; La dur&#233;e du sort augmente de 2 jours par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Protection contre les &#233;nergies destructives (M).&lt;/b&gt; S’il est lanc&#233; pour prot&#233;ger de la chaleur, augmente de 5 le nombre de d&#233;g&#226;ts de feu absorb&#233;s.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Rayon de givre (F).&lt;/b&gt; Le sort inflige +1 point de d&#233;g&#226;ts.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Rayon de givre (M).&lt;/b&gt; Le sort cr&#233;e un gla&#231;on de vapeur d’eau gel&#233;e qui frappe la cible et inflige 1d3 points de d&#233;g&#226;ts perforants et 1 point de d&#233;g&#226;ts de froid.&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;sistance aux &#233;nergies destructives (M).&lt;/b&gt; S’il est lanc&#233; pour prot&#233;ger du feu, passe la r&#233;sistance au feu &#224; 12. &#192; partir du &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; 7, le personnage peut utiliser deux jarres de glace liquide comme composante de puissance pour passer la r&#233;sistance au feu &#224; 24. &#192; partir du &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; 11, le personnage peut utiliser trois jarres de glace liquide comme composante de puissance pour passer la r&#233;sistance au feu &#224; 36.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Graisse alchimique&quot; href=&quot;#Graisse alchimique&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Graisse alchimique (&lt;a class=&quot;pagelink&quot; href=&quot;Graisse-Alchimique-(Objet).html&quot; title=&quot;Graisse alchimique&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Graisse_alchimique__lien__7&quot; href=&quot;#Graisse_alchimique__lien__7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cette substance est parfaite pour am&#233;liorer les sorts qui affectent ou cr&#233;&#233;ent des surfaces.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (5 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Graisse.html&quot; title=&quot;Graisse&quot;&gt;graisse&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Fer.html&quot; title=&quot;Mur de fer&quot;&gt;mur de fer&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Pierre.html&quot; title=&quot;Mur de pierre&quot;&gt;mur de pierre&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Temp&#234;te-De-Neige.html&quot; title=&quot;Temp&#234;te de neige&quot;&gt;temp&#234;te de neige&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; La graisse alchimique peut &#234;tre utilis&#233;e comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Graisse (M).&lt;/b&gt; Augmente de &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; des cr&#233;atures affect&#233;es et le bonus aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; des armures graiss&#233;es de 1.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Mur de fer (M).&lt;/b&gt; Pour chaque pot de graisse utilis&#233; comme composante de puissance, le personnage peut d&#233;signer un carr&#233; de 3 m du &lt;i&gt;mur de fer&lt;/i&gt; qui devient glissant (+5 au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;).&lt;/li&gt;&lt;li&gt;&lt;b&gt;Mur de pierre (M).&lt;/b&gt; Pour chaque pot de graisse utilis&#233; comme composante de puissance, le personnage peut d&#233;signer un carr&#233; de 3 m du &lt;i&gt;mur de pierre&lt;/i&gt; qui devient glissant (+5 au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Escalade.html&quot; title=&quot;Escalade&quot;&gt;Escalade&lt;/a&gt;).&lt;/li&gt;&lt;li&gt;&lt;b&gt;Temp&#234;te de neige (M).&lt;/b&gt; Augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Poil &#224; gratter&quot; href=&quot;#Poil &#224; gratter&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Poil &#224; gratter (&lt;a class=&quot;pagelink&quot; href=&quot;Poil-&#192;-Gratter-(Objet).html&quot; title=&quot;Poil &#224; gratter&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Poil_&#224;_gratter__lien__8&quot; href=&quot;#Poil_&#224;_gratter__lien__8&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Cette poudre peut rendre particuli&#232;rement irritant un sort habituellement anodin.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (60 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Nu&#233;e-Grouillante.html&quot; title=&quot;Nu&#233;e grouillante&quot;&gt;nu&#233;e grouillante&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poussi&#232;re-Scintillante.html&quot; title=&quot;Poussi&#232;re scintillante&quot;&gt;poussi&#232;re scintillante&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;R&#233;pulsif.html&quot; title=&quot;R&#233;pulsif&quot;&gt;r&#233;pulsif&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; Le poil &#224; gratter peut &#234;tre utilis&#233; comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Nu&#233;e grouillante (M).&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de la &lt;a class=&quot;pagelink&quot; href=&quot;Distraction-(Capacit&#233;).html&quot; title=&quot;Distraction (Ext)&quot;&gt;distraction&lt;/a&gt; de la nu&#233;e augmente de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Poussi&#232;re scintillante (M).&lt;/b&gt; Pour chaque sachet de poil &#224; gratter utilis&#233; comme composante de puissance, le personnage peut d&#233;signer une cr&#233;ature dans la zone d’effet qui sera affect&#233;e par le &lt;a class=&quot;pagelink&quot; href=&quot;Armes-Alchimiques.html#Poil &#224; gratter&quot; title=&quot;Armes alchimiques&quot;&gt;poil &#224; gratter&lt;/a&gt; (DD 12).&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;pulsif (M).&lt;/b&gt; La premi&#232;re vermine &#224; entrer dans l’&#233;manation est sujette aux effets du &lt;a class=&quot;pagelink&quot; href=&quot;Poil-&#192;-Gratter-(Objet).html&quot; title=&quot;Poil &#224; gratter&quot;&gt;poil &#224; gratter&lt;/a&gt; (DD 15). Chaque sachet de poil &#224; gratter utilis&#233; au-del&#224; du premier permet au sort d’affecter une autre vermine entrant dans l’&#233;manation. Une nu&#233;e de vermines compte comme une seule vermine dans le cadre de cet effet.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Poudre &#224; flash&quot; href=&quot;#Poudre &#224; flash&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Poudre &#224; flash (&lt;a class=&quot;pagelink&quot; href=&quot;Poudre-&#192;-Flash-(Objet).html&quot; title=&quot;Poudre &#224; flash&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Poudre_&#224;_flash__lien__9&quot; href=&quot;#Poudre_&#224;_flash__lien__9&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Utile comme distraction, la poudre &#224; flash rend les sorts qui produisent des explosions de lumi&#232;re plus dangereux.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (50 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Illumination.html&quot; title=&quot;Illumination&quot;&gt;illumination&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pyrotechnie.html&quot; title=&quot;Pyrotechnie&quot;&gt;pyrotechnie&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; La poudre &#224; flash peut &#234;tre utilis&#233;e comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Illumination (M).&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; du sort augmente de 2.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pyrotechnie (M).&lt;/b&gt; Lorsqu’il est utilis&#233; pour cr&#233;er un feu d’artifice, augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; de 1 et la dur&#233;e de l’aveuglement de 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Pierre tonnerre&quot; href=&quot;#Pierre tonnerre&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Pierre tonnerre (&lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Tonnerre-(Objet).html&quot; title=&quot;Pierre tonnerre&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Pierre_tonnerre__lien__10&quot; href=&quot;#Pierre_tonnerre__lien__10&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Bien qu&#39;elles soient suffisamment efficaces &#224; elles seules, ces pierres ont des interactions utiles avec certains sorts.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (30 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Alarme.html&quot; title=&quot;Alarme&quot;&gt;alarme&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Glyphe-De-Garde.html&quot; title=&quot;Glyphe de garde&quot;&gt;glyphe de garde&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; Les pierres tonnerres peuvent &#234;tre utilis&#233;es comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Alarme (M).&lt;/b&gt; S’il est lanc&#233; comme une alarme mentale, le personnage peut faire en sorte que le sort manifeste une alarme mentale et une alarme audible en m&#234;me temps. S’il est lanc&#233; comme une alarme audible, l’alarme est aussi bruyante qu’une pierre tonnerre et affecte les cr&#233;atures dans une &#233;tendue de 3 m de rayon comme si une &lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Tonnerre-(Objet).html&quot; title=&quot;Pierre tonnerre&quot;&gt;pierre tonnerre&lt;/a&gt; avait d&#233;ton&#233; &#224; cet endroit.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Glyphe de garde (M).&lt;/b&gt; Les cr&#233;atures qui ratent leur jet de sauvegarde contre un glyphe explosif sont &#233;galement &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Assourdi.html&quot; title=&quot;Assourdi&quot;&gt;assourdies&lt;/a&gt; comme avec une &lt;a class=&quot;pagelink&quot; href=&quot;Pierre-Tonnerre-(Objet).html&quot; title=&quot;Pierre tonnerre&quot;&gt;pierre tonnerre&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;
&lt;a href=&quot;/Wiki/Pathfinder-RPG.Armurerie de laventurier (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Adventurer&#39;s Armory/Armurerie de l&#39;aventurier&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoAA.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;Sacoche immobilisante&quot; href=&quot;#Sacoche immobilisante&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;
&lt;h3 class=&quot;separator&quot;&gt;Sacoche immobilisante (&lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-Immobilisante-(Objet).html&quot; title=&quot;Sacoche immobilisante&quot;&gt;lien&lt;/a&gt;)&lt;a class=&quot;headeranchor&quot; id=&quot;Sacoche_immobilisante__lien__11&quot; href=&quot;#Sacoche_immobilisante__lien__11&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Ces sacoches peuvent rendre un sort contraignant encore pire.
&lt;hr&gt;
&lt;b&gt;Doses&lt;/b&gt; 1 (50 po) ; &lt;b&gt;Sorts&lt;/b&gt; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lenteur.html&quot; title=&quot;Lenteur&quot;&gt;lenteur&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tentacules-Noirs.html&quot; title=&quot;Tentacules noirs&quot;&gt;tentacules noirs&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Toile-Daraign&#233;e.html&quot; title=&quot;Toile d&amp;#39;araign&#233;e&quot;&gt;toile d’araign&#233;e&lt;/a&gt;&lt;/i&gt;  
&lt;b&gt;Effet&lt;/b&gt; Les sacoches immobilisantes peuvent &#234;tre utilis&#233;es comme composante de puissance des mani&#232;res suivantes :
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Lenteur (M).&lt;/b&gt; Pour chaque sacoche immobilisante utilis&#233;e comme composante de puissance, le personnage peut d&#233;sign&#233;e une cr&#233;ature ralentie qui sera affect&#233;e par une &lt;a class=&quot;pagelink&quot; href=&quot;Sacoche-Immobilisante-(Objet).html&quot; title=&quot;Sacoche immobilisante&quot;&gt;sacoche immobilisante&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Tentacules noirs (M).&lt;/b&gt; Pour chaque sacoche immobilisante utilis&#233;e comme composante de puissance, le personnage peut relancer le test de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Lutte.html&quot; title=&quot;lutte&quot;&gt;lutte&lt;/a&gt; des tentacules contre une cr&#233;ature de son choix.&lt;/li&gt;&lt;li&gt;&lt;b&gt;Toile d’araign&#233;e (M).&lt;/b&gt; Augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; pour se lib&#233;rer en faisant un test de &lt;a class=&quot;pagelink&quot; href=&quot;Manoeuvres-Offensives.html&quot; title=&quot;Les manœuvres offensives&quot;&gt;manoeuvre offensive&lt;/a&gt; ou d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#201;vasion&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
